// Dates spread over four centuries, to check the weekday and day of the year.
let seed = 7;
const next = (n) => {
  seed = (seed * 1103515245 + 12345) % 2147483648;
  return seed % n;
};
const pad = (n, w = 2) => String(n).padStart(w, "0");
for (let k = 0; k < 60; k++) {
  const y = 1850 + next(300);
  const m = 1 + next(12);
  const d = 1 + next(28 + (m === 2 ? 0 : 3));
  const t = `${pad(next(24))}:${pad(next(60))}:${pad(next(61))}`;
  const j = 1 + next(365);
  CASES.push(
    [`strptime("%Y-%m-%dT%H:%M:%SZ")`, `${y}-${pad(m)}-${pad(d)}T${t}Z`],
    [`strptime("%Y-%m-%dT%H:%M:%SZ") | mktime`, `${y}-${pad(m)}-${pad(d)}T${t}Z`],
    [
      `strptime("%d %B %Y %T")`,
      `${d} ${["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"][m - 1]} ${y} ${t}`,
    ],
    [`strptime("%Y %j") | ., mktime`, `${y} ${pad(j, 3)}`],
    [`strptime("%m/%d/%y") | ., todate`, `${pad(m)}/${pad(d)}/${pad(y % 100)}`],
  );
}

function record([program, input = null]) {
  const res = spawnSync("jq", ["-c", program], {
    input: JSON.stringify(input),
    encoding: "utf8",
    timeout: 20_000,
    env: { ...process.env, TZ: "UTC" },
  });
  if (res.error?.code === "ENOENT") throw new Error("jq is not on PATH");
  const out = { program, input };
  if (res.status !== 0) return { ...out, error: true };
  const outputs = res.stdout
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line));
  return { ...out, outputs };
}

const seen = new Set();
const cases = [];
for (const c of CASES) {
  const key = JSON.stringify(c);
  if (seen.has(key)) continue;
  seen.add(key);
  cases.push(record(c));
}
const here = dirname(fileURLToPath(import.meta.url));
writeFileSync(join(here, "jq-review-cases.json"), `${JSON.stringify(cases, null, 1)}\n`);
console.log(`${cases.length} cases, ${cases.filter((c) => c.error).length} of them errors`);
